insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('gen-49-27','gen','창세기',49,27,'베냐민은 물어뜯는 이리라 아침에는 빼앗은 것을 먹고 저녁에는 움킨 것을 나누리로다',1501),
('gen-49-28','gen','창세기',49,28,'이들은 이스라엘의 열두 지파라 이와 같이 그들의 아버지가 그들에게 말하고 그들에게 축복하였으니 곧 그들 각 사람의 분량대로 축복하였더라',1502),
('gen-49-29','gen','창세기',49,29,'그가 그들에게 명하여 이르되 내가 내 조상들에게로 돌아가리니 나를 헷 사람 에브론의 밭에 있는 굴에 우리 선조와 함께 장사하라',1503),
('gen-49-30','gen','창세기',49,30,'이 굴은 가나안 땅 마므레 앞 막벨라 밭에 있는 것이라 아브라함이 헷 사람 에브론에게서 밭과 함께 사서 그의 매장지를 삼았으므로',1504),
('gen-49-31','gen','창세기',49,31,'아브라함과 그의 아내 사라가 거기 장사되었고 이삭과 그의 아내 리브가도 거기 장사되었으며 나도 레아를 그 곳에 장사하였노라',1505),
('gen-49-32','gen','창세기',49,32,'이 밭과 거기 있는 굴은 헷 사람에게서 산 것이니라',1506),
('gen-49-33','gen','창세기',49,33,'야곱이 아들에게 명하기를 마치고 그 발을 침상에 모으고 숨을 거두니 그의 백성에게로 돌아갔더라',1507),
('gen-50-1','gen','창세기',50,1,'요셉이 그의 아버지 얼굴에 구푸려 울며 입맞추고',1508),
('gen-50-2','gen','창세기',50,2,'그 수종 드는 의원에게 명하여 아버지의 몸을 향으로 처리하게 하매 의원이 이스라엘에게 그대로 하되',1509),
('gen-50-3','gen','창세기',50,3,'사십 일이 걸렸으니 향으로 처리하는 데는 이 날수가 걸림이며 애굽 사람들은 칠십 일 동안 그를 위하여 곡하였더라',1510),
('gen-50-4','gen','창세기',50,4,'곡하는 기한이 지나매 요셉이 바로의 궁에 말하여 이르되 내가 너희에게 은혜를 입었으면 원하건대 바로의 귀에 아뢰기를',1511),
('gen-50-5','gen','창세기',50,5,'우리 아버지가 나로 맹세하게 하여 이르되 내가 죽거든 가나안 땅에 내가 파 놓은 묘실에 나를 장사하라 하였나니 나로 올라가서 아버지를 장사하게 하소서 내가 다시 오리이다 하라 하였더니',1512),
('gen-50-6','gen','창세기',50,6,'바로가 이르되 그가 네게 시킨 맹세대로 올라가서 네 아버지를 장사하라',1513),
('gen-50-7','gen','창세기',50,7,'요셉이 자기 아버지를 장사하러 올라가니 바로의 모든 신하와 바로 궁의 원로들과 애굽 땅의 모든 원로와',1514),
('gen-50-8','gen','창세기',50,8,'요셉의 온 집과 그의 형제들과 그의 아버지의 집이 그와 함께 올라가고 그들의 어린 아이들과 양 떼와 소 떼만 고센 땅에 남겼으며',1515),
('gen-50-9','gen','창세기',50,9,'병거와 기병이 요셉을 따라 올라가니 그 떼가 심히 컸더라',1516),
('gen-50-10','gen','창세기',50,10,'그들이 요단 강 건너편 아닷 타작 마당에 이르러 거기서 크게 울고 애통하며 요셉이 아버지를 위하여 칠 일 동안 애곡하였더니',1517),
('gen-50-11','gen','창세기',50,11,'그 땅 거민 가나안 백성들이 아닷 마당의 애통을 보고 이르되 이는 애굽 사람의 큰 애통이라 하였으므로 그 땅 이름을 아벨미스라임이라 하였으니 곧 요단 강 건너편이더라',1518),
('gen-50-12','gen','창세기',50,12,'야곱의 아들들이 아버지가 그들에게 명령한 대로 그를 위해 따라 행하여',1519),
('gen-50-13','gen','창세기',50,13,'그를 가나안 땅으로 메어다가 마므레 앞 막벨라 밭 굴에 장사하였으니 이는 아브라함이 헷 족속 에브론에게 밭과 함께 사서 매장지를 삼은 곳이더라',1520),
('gen-50-14','gen','창세기',50,14,'요셉이 아버지를 장사한 후에 자기 형제와 호상꾼과 함께 애굽으로 돌아왔더라',1521),
('gen-50-15','gen','창세기',50,15,'요셉의 형제들이 그들의 아버지가 죽었음을 보고 말하되 요셉이 혹시 우리를 미워하여 우리가 그에게 행한 모든 악을 다 갚지나 아니할까 하고',1522),
('gen-50-16','gen','창세기',50,16,'요셉에게 말을 전하여 이르되 당신의 아버지가 돌아가시기 전에 명령하여 이르시기를',1523),
('gen-50-17','gen','창세기',50,17,'너희는 이같이 요셉에게 이르라 네 형들이 네게 악을 행하였을지라도 이제 바라건대 그들의 허물과 죄를 용서하라 하셨나니 당신 아버지의 하나님의 종들인 우리 죄를 이제 용서하소서 하매 요셉이 그들이 그에게 하는 말을 들을 때에 울었더라',1524),
('gen-50-18','gen','창세기',50,18,'그의 형들이 또 친히 와서 요셉의 앞에 엎드려 이르되 우리는 당신의 종들이니이다',1525),
('gen-50-19','gen','창세기',50,19,'요셉이 그들에게 이르되 두려워하지 마소서 내가 하나님을 대신하리이까',1526),
('gen-50-20','gen','창세기',50,20,'당신들은 나를 해하려 하였으나 하나님은 그것을 선으로 바꾸사 오늘과 같이 많은 백성의 생명을 구원하게 하시려 하셨나니',1527),
('gen-50-21','gen','창세기',50,21,'당신들은 두려워하지 마소서 내가 당신들과 당신들의 자녀를 기르리이다 하고 그들을 간곡한 말로 위로하였더라',1528),
('gen-50-22','gen','창세기',50,22,'요셉이 그의 아버지의 가족과 함께 애굽에 거주하여 백십 세를 살며',1529),
('gen-50-23','gen','창세기',50,23,'에브라임의 자손 삼대를 보았으며 므낫세의 아들 마길의 아들들도 요셉의 슬하에서 양육되었더라',1530),
('gen-50-24','gen','창세기',50,24,'요셉이 그의 형제들에게 이르되 나는 죽을 것이나 하나님이 당신들을 돌보시고 당신들을 이 땅에서 인도하여 내사 아브라함과 이삭과 야곱에게 맹세하신 땅에 이르게 하시리라 하고',1531),
('gen-50-25','gen','창세기',50,25,'요셉이 또 이스라엘 자손에게 맹세시켜 이르기를 하나님이 반드시 당신들을 돌보시리니 당신들은 여기서 내 해골을 메고 올라가겠다 하라 하였더라',1532),
('gen-50-26','gen','창세기',50,26,'요셉이 백십 세에 죽으매 그들이 그의 몸에 향 재료를 넣고 애굽에서 입관하였더라',1533),
('exo-1-1','exo','출애굽기',1,1,'야곱과 함께 각각 자기 가족을 데리고 애굽에 이른 이스라엘 아들들의 이름은 이러하니',1534),
('exo-1-2','exo','출애굽기',1,2,'르우벤과 시므온과 레위와 유다와',1535),
('exo-1-3','exo','출애굽기',1,3,'잇사갈과 스불론과 베냐민과',1536),
('exo-1-4','exo','출애굽기',1,4,'단과 납달리와 갓과 아셀이요',1537),
('exo-1-5','exo','출애굽기',1,5,'야곱의 허리에서 나온 사람이 모두 칠십이요 요셉은 애굽에 있었더라',1538),
('exo-1-6','exo','출애굽기',1,6,'요셉과 그의 모든 형제와 그 시대의 사람은 다 죽었고',1539),
('exo-1-7','exo','출애굽기',1,7,'이스라엘 자손은 생육하고 불어나 번성하고 매우 강하여 온 땅에 가득하게 되었더라',1540),
('exo-1-8','exo','출애굽기',1,8,'요셉을 알지 못하는 새 왕이 일어나 애굽을 다스리더니',1541),
('exo-1-9','exo','출애굽기',1,9,'그가 그 백성에게 이르되 이 백성 이스라엘 자손이 우리보다 많고 강하도다',1542),
('exo-1-10','exo','출애굽기',1,10,'자, 우리가 그들에게 대하여 지혜롭게 하자 두렵건대 그들이 더 많게 되면 전쟁이 일어날 때에 우리 대적과 합하여 우리와 싸우고 이 땅에서 나갈까 하노라 하고',1543),
('exo-1-11','exo','출애굽기',1,11,'감독들을 그들 위에 세우고 그들에게 무거운 짐을 지워 괴롭게 하여 그들에게 바로를 위하여 국고성 비돔과 라암셋을 건축하게 하니라',1544),
('exo-1-12','exo','출애굽기',1,12,'그러나 학대를 받을수록 더욱 번성하여 퍼져나가니 애굽 사람이 이스라엘 자손으로 말미암아 근심하여',1545),
('exo-1-13','exo','출애굽기',1,13,'이스라엘 자손에게 일을 엄하게 시켜',1546),
('exo-1-14','exo','출애굽기',1,14,'어려운 노동으로 그들의 생활을 괴롭게 하니 곧 흙 이기기와 벽돌 굽기와 농사의 여러 가지 일이라 그 시키는 일이 모두 엄하였더라',1547),
('exo-1-15','exo','출애굽기',1,15,'애굽 왕이 히브리 산파 십브라라 하는 사람과 부아라 하는 사람에게 말하여',1548),
('exo-1-16','exo','출애굽기',1,16,'이르되 너희는 히브리 여인을 위하여 해산을 도울 때에 그 자리를 살펴서 아들이거든 그를 죽이고 딸이거든 살려두라',1549),
('exo-1-17','exo','출애굽기',1,17,'그러나 산파들이 하나님을 두려워하여 애굽 왕의 명령을 어기고 남자 아기들을 살린지라',1550),
('exo-1-18','exo','출애굽기',1,18,'애굽 왕이 산파를 불러 그들에게 이르되 너희가 어찌하여 이같이 남자 아기들을 살렸느냐',1551),
('exo-1-19','exo','출애굽기',1,19,'산파가 바로에게 대답하되 히브리 여인은 애굽 여인과 같지 아니하고 건장하여 산파가 그들에게 이르기 전에 해산하였더이다 하매',1552),
('exo-1-20','exo','출애굽기',1,20,'하나님이 그 산파들에게 은혜를 베푸시니 그 백성은 번성하고 매우 강해지니라',1553),
('exo-1-21','exo','출애굽기',1,21,'그 산파들은 하나님을 경외하였으므로 하나님이 그들의 집안을 흥왕하게 하신지라',1554),
('exo-1-22','exo','출애굽기',1,22,'그러므로 바로가 그의 모든 백성에게 명령하여 이르되 아들이 태어나거든 너희는 그를 나일 강에 던지고 딸이거든 살려두라 하였더라',1555),
('exo-2-1','exo','출애굽기',2,1,'레위 가족 중 한 사람이 가서 레위 여자에게 장가 들어',1556),
('exo-2-2','exo','출애굽기',2,2,'그 여자가 임신하여 아들을 낳으니 그가 잘 생긴 것을 보고 석 달 동안 그를 숨겼으나',1557),
('exo-2-3','exo','출애굽기',2,3,'더 숨길 수 없게 되매 그를 위하여 갈대 상자를 가져다가 역청과 나무 진을 칠하고 아기를 거기 담아 나일 강 가 갈대 사이에 두고',1558),
('exo-2-4','exo','출애굽기',2,4,'그의 누이가 어떻게 되는지를 알려고 멀리 섰더니',1559),
('exo-2-5','exo','출애굽기',2,5,'바로의 딸이 목욕하러 나일 강으로 내려오고 시녀들은 나일 강 가를 거닐 때에 그가 갈대 사이의 상자를 보고 시녀를 보내어 가져다가',1560),
('exo-2-6','exo','출애굽기',2,6,'열고 그 아기를 보니 아기가 우는지라 그가 그를 불쌍히 여겨 이르되 이는 히브리 사람의 아기로다',1561),
('exo-2-7','exo','출애굽기',2,7,'그의 누이가 바로의 딸에게 이르되 내가 가서 당신을 위하여 히브리 여인 중에서 유모를 불러다가 이 아기에게 젖을 먹이게 하리이까',1562),
('exo-2-8','exo','출애굽기',2,8,'바로의 딸이 그에게 이르되 가라 하매 그 소녀가 가서 그 아기의 어머니를 불러오니',1563),
('exo-2-9','exo','출애굽기',2,9,'바로의 딸이 그에게 이르되 이 아기를 데려다가 나를 위하여 젖을 먹이라 내가 그 삯을 주리라 여인이 아기를 데려다가 젖을 먹이더니',1564),
('exo-2-10','exo','출애굽기',2,10,'그 아기가 자라매 바로의 딸에게로 데려가니 그가 그의 아들이 되니라 그가 그의 이름을 모세라 하여 이르되 이는 내가 그를 물에서 건져내었음이라 하였더라',1565),
('exo-2-11','exo','출애굽기',2,11,'모세가 장성한 후에 한번은 자기 형제들에게 나가서 그들이 고되게 노동하는 것을 보더니 어떤 애굽 사람이 한 히브리 사람 곧 자기 형제를 치는 것을 본지라',1566),
('exo-2-12','exo','출애굽기',2,12,'좌우를 살펴 사람이 없음을 보고 그 애굽 사람을 쳐죽여 모래 속에 감추니라',1567),
('exo-2-13','exo','출애굽기',2,13,'이튿날 다시 나가니 두 히브리 사람이 서로 싸우는지라 그 잘못한 사람에게 이르되 네가 어찌하여 동포를 치느냐 하매',1568),
('exo-2-14','exo','출애굽기',2,14,'그가 이르되 누가 너를 우리를 다스리는 자와 재판관으로 삼았느냐 네가 애굽 사람을 죽인 것처럼 나도 죽이려느냐 모세가 두려워하여 이르되 일이 탄로되었도다',1569),
('exo-2-15','exo','출애굽기',2,15,'바로가 이 일을 듣고 모세를 죽이고자 하여 찾는지라 모세가 바로의 낯을 피하여 미디안 땅에 머물며 하루는 우물 곁에 앉았더라',1570),
('exo-2-16','exo','출애굽기',2,16,'미디안 제사장에게 일곱 딸이 있었더니 그들이 와서 물을 길어 구유에 채우고 그들의 아버지의 양 떼에게 먹이려 하는데',1571),
('exo-2-17','exo','출애굽기',2,17,'목자들이 와서 그들을 쫓는지라 모세가 일어나 그들을 도와 그 양 떼에게 먹이니라',1572),
('exo-2-18','exo','출애굽기',2,18,'그들이 그들의 아버지 르우엘에게 이를 때에 아버지가 이르되 너희가 오늘은 어찌하여 이같이 속히 돌아오느냐',1573),
('exo-2-19','exo','출애굽기',2,19,'그들이 이르되 한 애굽 사람이 우리를 목자들의 손에서 건져내고 우리를 위하여 물을 길어 양 떼에게 먹였나이다',1574),
('exo-2-20','exo','출애굽기',2,20,'아버지가 딸들에게 이르되 그 사람이 어디에 있느냐 너희가 어찌하여 그 사람을 버려두고 왔느냐 그를 청하여 음식을 대접하라 하였더라',1575),
('exo-2-21','exo','출애굽기',2,21,'모세가 그와 동거하기를 기뻐하매 그가 그의 딸 십보라를 모세에게 주었더니',1576),
('exo-2-22','exo','출애굽기',2,22,'그가 아들을 낳으매 모세가 그의 이름을 게르솜이라 하여 이르되 내가 타국에서 나그네가 되었음이라 하였더라',1577),
('exo-2-23','exo','출애굽기',2,23,'여러 해 후에 애굽 왕은 죽었고 이스라엘 자손은 고된 노동으로 말미암아 탄식하며 부르짖으니 그 고된 노동으로 말미암아 부르짖는 소리가 하나님께 상달된지라',1578),
('exo-2-24','exo','출애굽기',2,24,'하나님이 그들의 고통 소리를 들으시고 하나님이 아브라함과 이삭과 야곱에게 세운 그의 언약을 기억하사',1579),
('exo-2-25','exo','출애굽기',2,25,'하나님이 이스라엘 자손을 돌보셨고 하나님이 그들을 기억하셨더라',1580),
('exo-3-1','exo','출애굽기',3,1,'모세가 그의 장인 미디안 제사장 이드로의 양 떼를 치더니 그 떼를 광야 서쪽으로 인도하여 하나님의 산 호렙에 이르매',1581),
('exo-3-2','exo','출애굽기',3,2,'여호와의 사자가 떨기나무 가운데로부터 나오는 불꽃 안에서 그에게 나타나시니라 그가 보니 떨기나무에 불이 붙었으나 그 떨기나무가 사라지지 아니하는지라',1582),
('exo-3-3','exo','출애굽기',3,3,'이에 모세가 이르되 내가 돌이켜 가서 이 큰 광경을 보리라 떨기나무가 어찌하여 타지 아니하는고 하니 그 때에',1583),
('exo-3-4','exo','출애굽기',3,4,'여호와께서 그가 보려고 돌이켜 오는 것을 보신지라 하나님이 떨기나무 가운데서 그를 불러 이르시되 모세야 모세야 하시매 그가 이르되 내가 여기 있나이다',1584),
('exo-3-5','exo','출애굽기',3,5,'하나님이 이르시되 이리로 가까이 오지 말라 네가 선 곳은 거룩한 땅이니 네 발에서 신을 벗으라',1585),
('exo-3-6','exo','출애굽기',3,6,'또 이르시되 나는 네 조상의 하나님이니 아브라함의 하나님, 이삭의 하나님, 야곱의 하나님이니라 모세가 하나님 뵈옵기를 두려워하여 얼굴을 가리매',1586),
('exo-3-7','exo','출애굽기',3,7,'여호와께서 이르시되 내가 애굽에 있는 내 백성의 고통을 분명히 보고 그들이 그들의 감독자로 말미암아 부르짖음을 듣고 그 근심을 알고',1587),
('exo-3-8','exo','출애굽기',3,8,'내가 내려가서 그들을 애굽인의 손에서 건져내고 그들을 그 땅에서 인도하여 아름답고 광대한 땅, 젖과 꿀이 흐르는 땅 곧 가나안 족속, 헷 족속, 아모리 족속, 브리스 족속, 히위 족속, 여부스 족속의 지방에 데려가려 하노라',1588),
('exo-3-9','exo','출애굽기',3,9,'이제 가라 이스라엘 자손의 부르짖음이 내게 달하고 애굽 사람이 그들을 괴롭히는 학대도 내가 보았으니',1589),
('exo-3-10','exo','출애굽기',3,10,'이제 내가 너를 바로에게 보내어 너에게 내 백성 이스라엘 자손을 애굽에서 인도하여 내게 하리라',1590),
('exo-3-11','exo','출애굽기',3,11,'모세가 하나님께 아뢰되 내가 누구이기에 바로에게 가며 이스라엘 자손을 애굽에서 인도하여 내리이까',1591),
('exo-3-12','exo','출애굽기',3,12,'하나님이 이르시되 내가 반드시 너와 함께 있으리라 네가 그 백성을 애굽에서 인도하여 낸 후에 너희가 이 산에서 하나님을 섬기리니 이것이 내가 너를 보낸 증거니라',1592),
('exo-3-13','exo','출애굽기',3,13,'모세가 하나님께 아뢰되 내가 이스라엘 자손에게 가서 이르기를 너희의 조상의 하나님이 나를 너희에게 보내셨다 하면 그들이 내게 묻기를 그의 이름이 무엇이냐 하리니 내가 무엇이라고 그들에게 말하리이까',1593),
('exo-3-14','exo','출애굽기',3,14,'하나님이 모세에게 이르시되 나는 스스로 있는 자이니라 또 이르시되 너는 이스라엘 자손에게 이같이 이르기를 스스로 있는 자가 나를 너희에게 보내셨다 하라',1594),
